const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const BASE = 'E:/WT/save-tokens/test-scenarios/without-context-mode/scenario-1-日志分析/extracted';
const OUTPUT = 'E:/WT/save-tokens/test-scenarios/with-context-mode/scenario-1-日志分析/electronicdirections_analysis.txt';

let output = [];
output.push('='.repeat(80));
output.push('  electronicdirections (com.wtcl.electronicdirections) 日志分析');
output.push('  设备: LS6ANE2R3SK200031 (智己 LS6)');
output.push('  提取时间: ' + new Date().toISOString());
output.push('='.repeat(80));
output.push('');

// Search sys_log from APLog_10
const sysLogPath = path.join(BASE, 'resources/debuglogger/mobilelog/APLog_2026_0818_204728__10/sys_log_13__2026_0818_205610.gz');
try {
  output.push('--- sys_log (APLog_10) ---');
  const result = execSync(`gunzip -c "${sysLogPath}" 2>/dev/null | grep -i "com.wtcl.electronicdirections"`, {encoding: 'utf8', maxBuffer: 50*1024*1024});
  output.push(result);
  output.push(`Entries: ${result.split('\\n').filter(l=>l.trim()).length}`);
} catch(e) { output.push('No entries or error: ' + e.message); }

output.push('');

// Search events_log from APLog_10
const eventsLogPath = path.join(BASE, 'resources/debuglogger/mobilelog/APLog_2026_0818_204728__10/events_log_12__2026_0818_205610.gz');
try {
  output.push('--- events_log (APLog_10) ---');
  const result = execSync(`gunzip -c "${eventsLogPath}" 2>/dev/null | grep -i "com.wtcl.electronicdirections"`, {encoding: 'utf8', maxBuffer: 50*1024*1024});
  output.push(result);
  output.push(`Entries: ${result.split('\\n').filter(l=>l.trim()).length}`);
} catch(e) { output.push('No entries or error: ' + e.message); }

output.push('');

// Search crash_log from APLog_10
const crashLogPath = path.join(BASE, 'resources/debuglogger/mobilelog/APLog_2026_0818_204728__10/crash_log_14__2026_0818_205610.gz');
try {
  output.push('--- crash_log (APLog_10) ---');
  const result = execSync(`gunzip -c "${crashLogPath}" 2>/dev/null | grep -i "com.wtcl.electronicdirections"`, {encoding: 'utf8', maxBuffer: 50*1024*1024});
  output.push(result || '(empty - no crash entries for this app)');
} catch(e) { output.push('(empty or error)'); }

output.push('');

// Search all main_log files from APLog_10
const ap10dir = path.join(BASE, 'resources/debuglogger/mobilelog/APLog_2026_0818_204728__10');
const mainLogs = fs.readdirSync(ap10dir).filter(f => f.startsWith('main_log_') && f.endsWith('.gz'));
for (const f of mainLogs.sort()) {
  try {
    const result = execSync(`gunzip -c "${path.join(ap10dir, f)}" 2>/dev/null | grep -i "com.wtcl.electronicdirections"`, {encoding: 'utf8', maxBuffer: 50*1024*1024});
    if (result.trim()) {
      output.push(`--- ${f} ---`);
      output.push(result);
    }
  } catch(e) { /* no matches */ }
}

output.push('');
output.push('='.repeat(80));
output.push('  分析摘要');
output.push('='.repeat(80));

fs.writeFileSync(OUTPUT, output.join('\\n'), 'utf8');
console.log('Extraction complete. Written to: ' + OUTPUT);
console.log('Total lines: ' + output.length);

